import heapq
class Solution:
    def getSkyline(self, buildings: List[List[int]]) -> List[List[int]]:
        points = []
        for L, R, H in buildings:
            points.append((L, -H, 0)) # 0 means start of building
            points.append((R, H, 1)) # 1 means end of building
        points.sort(key = lambda x: (x[0], -x[1]))

        maxHeap = []
        res = [[0, 0]]
        prev = 0
        for x, y, _ in points:
            if y<0:
                heapq.heappush(maxHeap, y)
            else:
                maxHeap.remove(y)
                heapq.heapify(maxHeap)
            currMax = maxHeap[0] if maxHeap else 0
            if currMax != prev:
                res.append([x, currMax])
                prev = currMax
        return res[1:]

This algorithm has a time complexity of O(n log n) due to the sorting of points and another O(n log n) due to the heap operations and n is the number of buildings. So the overall time complexity is O(n log n) + O(n log n) = O(2n log n). Is my understanding correct?
